@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#0a0d12;--panel:#11161d;--white:#f4f3ef;--muted:#858d97;--lime:#d8ff3e;--cyan:#4ce1db;--line:rgba(255,255,255,.1);font-family:Manrope, sans-serif;color:var(--white);font-synthesis:none}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#090c10;color:var(--white);overflow:hidden}body{background:radial-gradient(ellipse at 38% 42%,#18202a 0,#0a0d12 64%)}button{font:inherit;color:inherit}.game-shell{height:100dvh;max-width:1800px;margin:auto;padding:0 40px;display:flex;flex-direction:column}.topbar{height:75px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:4}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{width:37px;height:37px;border:1px solid rgba(216,255,62,.62);display:grid;place-items:center;font:800 21px 'Barlow Condensed';letter-spacing:-2px;color:var(--lime);position:relative}.brand-mark span{color:white}.brand-name{font:800 17px 'Barlow Condensed';letter-spacing:1.6px}.brand-name span{color:var(--lime);margin-left:4px}.top-meta{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;font:10px 'DM Mono';letter-spacing:1.3px;color:#a6adb5}.top-meta i{width:1px;height:13px;background:#424850;margin:0 5px}.live-dot,.session-dot{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 11px #d8ff3e}.icon-btn{width:38px;height:38px;border:1px solid var(--line);background:transparent;color:var(--lime);font-size:20px;cursor:pointer}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 278px;gap:36px;flex:1;min-height:0;padding:27px 0 22px}.track-wrap{position:relative;overflow:hidden;background:#171c20;border:1px solid rgba(255,255,255,.14);min-height:350px;box-shadow:0 25px 80px #0007}#gameCanvas{position:absolute;width:100%;height:100%;inset:0;display:block}.track-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(0,0,0,.36),transparent 25%,transparent 73%,rgba(0,0,0,.24));box-shadow:inset 0 0 90px #0006}.hud-top{position:absolute;top:21px;left:23px;right:22px;display:flex;justify-content:space-between;align-items:center}.session-pill{display:flex;align-items:center;gap:8px;padding:8px 11px;background:#0a0d12c9;border:1px solid #ffffff20;font:10px 'DM Mono';letter-spacing:1.1px}.session-dot{width:6px;height:6px}.pause-btn{width:34px;height:34px;border:1px solid #ffffff32;background:#0b0e13bd;cursor:pointer;font-size:15px}.pause-glyph{color:var(--lime)}.score-hud{position:absolute;top:81px;left:25px;min-width:200px;text-shadow:0 2px 12px #0009}.score-label,.speed-unit,.car-class,.best-row,.eyebrow,.panel-kicker,.stat-list span,.result-stats span,.final-score span{font:10px 'DM Mono';letter-spacing:1.5px;color:#aab1b8}.score-value{font:800 43px 'Barlow Condensed';line-height:1.02;letter-spacing:2px}.combo-row{display:flex;align-items:center;gap:8px;margin-top:8px;font:9px 'DM Mono';letter-spacing:.9px;color:#d4d7da}.combo-badge{padding:4px 7px;background:var(--lime);color:#0a0d12;font-weight:bold}.speed-hud{position:absolute;bottom:25px;left:25px;display:flex;align-items:baseline;gap:6px;text-shadow:0 2px 12px #000}.speed-number{font:800 38px 'Barlow Condensed';letter-spacing:1px}.speed-unit{font-size:9px}.speed-bar{position:absolute;left:0;bottom:-9px;width:120px;height:2px;background:#ffffff30}.speed-bar span{height:100%;width:0;display:block;background:var(--lime);transition:width .1s}.drift-indicator{position:absolute;left:50%;top:20%;transform:translate(-50%,-10px);display:flex;gap:8px;align-items:center;opacity:0;color:var(--lime);font:10px 'DM Mono';letter-spacing:1.2px;transition:opacity .15s,transform .15s;text-shadow:0 0 12px #d8ff3e}.drift-indicator.active{opacity:1;transform:translate(-50%,0)}.drift-icon{font-size:22px}.toast{position:absolute;top:34%;left:50%;transform:translate(-50%,10px);font:700 12px 'Barlow Condensed';letter-spacing:1.4px;color:#fff;opacity:0;transition:.3s;text-shadow:0 2px 9px #000}.toast b{color:var(--lime);margin-left:8px}.toast.show{opacity:1;transform:translate(-50%,0)}.center-overlay,.pause-overlay,.result-overlay{position:absolute;z-index:2;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(5,8,11,.74),rgba(6,9,12,.32) 60%,rgba(3,5,7,.18));transition:opacity .35s}.center-overlay.hidden,.pause-overlay.hidden,.result-overlay.hidden{opacity:0;pointer-events:none}.overlay-card{width:min(410px,88%);margin-right:auto;margin-left:8%;padding:20px 10px}.eyebrow{display:flex;align-items:center;gap:9px;font-size:9px;color:#c0c6c6}.eyebrow-line{width:17px;height:1px;background:var(--lime)}h1,h2,p{margin:0}h1{font:900 clamp(60px,8vw,95px)/.79 'Barlow Condensed';letter-spacing:-1px;margin:24px 0 17px}h1 em,h2 em{font-style:normal;color:var(--lime)}.overlay-copy{max-width:300px;color:#c1c5c6;font-size:12px;line-height:1.7}.car-select{display:flex;align-items:center;gap:15px;border-top:1px solid #ffffff27;border-bottom:1px solid #ffffff27;margin:23px 0 17px;padding:12px 0}.car-arrow{width:27px;height:30px;border:1px solid #ffffff37;background:#10151bc9;color:var(--lime);font:26px 'Barlow Condensed';cursor:pointer}.car-info{display:flex;flex-direction:column;gap:3px;flex:1}.car-class{font-size:8px;color:#899198}.car-info strong{font:700 20px 'Barlow Condensed';letter-spacing:1px}.car-info>span:last-child{font:9px 'DM Mono';letter-spacing:.5px;color:#9da4aa}.start-btn{display:flex;align-items:center;justify-content:space-between;width:100%;height:48px;padding:0 16px;border:0;background:var(--lime);color:#0a0d12;cursor:pointer;font:800 13px 'Barlow Condensed';letter-spacing:1.1px;transition:.2s}.start-btn:hover{background:#e8ff81;transform:translateY(-1px)}.start-btn b{font-size:19px}.best-row{display:flex;justify-content:space-between;margin-top:13px;font-size:8px;color:#abb1b4}.best-row strong{color:#f4f3ef;font:11px 'DM Mono'}.side-panel{position:relative;padding:16px 2px 10px;display:flex;flex-direction:column}.panel-kicker{font-size:9px;display:flex;gap:10px;align-items:center;color:#c6cbd0}.panel-kicker span{color:var(--lime)}.side-panel h2{font:800 42px/.88 'Barlow Condensed';letter-spacing:.2px;margin:23px 0 13px}.brief-copy{font-size:11px;line-height:1.75;color:#9ca4ad;max-width:240px}.divider{height:1px;background:var(--line);margin:23px 0 17px}.stat-list{display:flex;flex-direction:column;gap:15px}.stat-list>div{display:flex;flex-direction:column;gap:5px}.stat-list span{font-size:8px;color:#717b85}.stat-list strong{font:10px 'DM Mono';letter-spacing:.5px;color:#e3e5e2}.weather-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--lime);margin-right:5px}.howto{margin-top:auto;border-top:1px solid var(--line);padding-top:17px}.howto .panel-kicker{margin-bottom:13px}.key-row{height:28px;display:flex;align-items:center;gap:4px;color:#838c95;font:8px 'DM Mono';letter-spacing:1px}.key-row>span:last-child{margin-left:7px}.key{display:grid;place-items:center;min-width:21px;height:21px;border:1px solid #ffffff2b;color:#dfe3e4;font:9px 'DM Mono';border-radius:3px}.key.wide{min-width:29px}.key:not(:first-child):not(.wide){margin-left:-2px}.panel-footer{display:flex;justify-content:space-between;margin-top:17px;padding-top:13px;border-top:1px solid var(--line);font:8px 'DM Mono';letter-spacing:1px;color:#646e77}.footer-mark{color:var(--lime)}.touch-controls{position:absolute;z-index:1;left:20px;right:20px;bottom:17px;display:none;align-items:flex-end;justify-content:space-between;pointer-events:none}.steer-group,.pedal-group{display:flex;gap:9px;pointer-events:auto}.pedal-group{align-items:flex-end}.control-btn{touch-action:none;user-select:none;-webkit-user-select:none;border:1px solid #ffffff50;background:#10151bbf;backdrop-filter:blur(8px);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer}.control-btn:active,.control-btn.pressed{background:#d8ff3e;color:#101419;border-color:var(--lime)}.steer{width:57px;height:57px;border-radius:50%;font:36px 'Barlow Condensed';color:var(--lime)}.handbrake,.throttle{width:55px;height:58px;flex-direction:column;gap:2px;border-radius:8px}.handbrake span{font:700 17px 'Barlow Condensed';color:var(--lime)}.control-btn small{font:7px 'DM Mono';letter-spacing:.5px}.throttle{height:77px;width:67px;background:#d8ff3e;color:#101419;border-color:#d8ff3e}.throttle span{font:800 17px 'Barlow Condensed'}.countdown{position:absolute;z-index:3;top:43%;left:50%;transform:translate(-50%,-50%);font:900 100px 'Barlow Condensed';color:var(--lime);text-shadow:0 0 40px #d8ff3e88}.countdown.hidden{display:none}.pause-overlay,.result-overlay{background:#070a0dd9;backdrop-filter:blur(6px)}.pause-card,.result-card{width:min(360px,85%);padding:30px;background:#11171f;border:1px solid #ffffff22;box-shadow:0 20px 80px #0009}.pause-card h2,.result-card h2{font:900 53px/.84 'Barlow Condensed';margin:21px 0 12px}.pause-card p{color:#a6aeb4;font-size:12px;margin-bottom:24px}.text-btn{display:block;margin:14px auto 0;border:0;background:none;color:#a9b0b4;text-decoration:underline;text-underline-offset:4px;font:9px 'DM Mono';letter-spacing:1px;cursor:pointer}.final-score{display:flex;flex-direction:column;gap:4px;margin:20px 0 12px}.final-score strong{font:800 42px 'Barlow Condensed';letter-spacing:2px;color:var(--lime)}.result-stats{display:flex;gap:40px;padding:13px 0 20px;border-top:1px solid var(--line);margin-bottom:5px}.result-stats>div{display:flex;flex-direction:column;gap:5px}.result-stats span{font-size:8px}.result-stats b{font:15px 'DM Mono'}.mobile-tip{display:none;color:#929ba2;font:9px 'DM Mono';letter-spacing:.3px;padding-bottom:max(9px,env(safe-area-inset-bottom));text-align:center}.mobile-tip span{color:var(--lime);margin-right:5px}
@media(max-width:900px){.game-shell{padding:0 22px}.game-layout{grid-template-columns:minmax(0,1fr) 235px;gap:22px}.overlay-card{margin-left:5%}.side-panel h2{font-size:36px}}
@media(max-width:700px){html,body{overflow:hidden}.game-shell{padding:0 0 env(safe-area-inset-bottom);height:100dvh}.topbar{height:53px;padding:0 15px}.brand-mark{width:29px;height:29px;font-size:17px}.brand{gap:8px}.brand-name{font-size:14px}.top-meta{font-size:8px;gap:6px;letter-spacing:.7px}.top-meta i{margin:0 2px}.icon-btn{width:32px;height:32px}.game-layout{display:block;padding:0;min-height:0;flex:1}.track-wrap{height:100%;min-height:0;border-left:0;border-right:0;border-top:0}.side-panel{display:none}.hud-top{top:12px;left:14px;right:13px}.session-pill{padding:7px 8px;font-size:8px}.pause-btn{width:31px;height:31px}.score-hud{left:15px;top:59px}.score-value{font-size:34px}.score-label{font-size:8px}.combo-row{margin-top:5px;font-size:8px}.speed-hud{left:15px;bottom:108px}.speed-number{font-size:32px}.speed-bar{width:90px}.center-overlay{background:linear-gradient(90deg,rgba(5,8,11,.77),rgba(6,9,12,.33) 80%)}.overlay-card{width:85%;max-width:400px;margin:0 0 0 5%;padding:10px 0}.eyebrow{font-size:8px;gap:6px}h1{font-size:64px;margin:20px 0 13px}.overlay-copy{font-size:11px;max-width:270px}.car-select{margin:17px 0 12px;padding:9px 0}.car-info strong{font-size:17px}.car-info>span:last-child{font-size:8px}.start-btn{height:44px}.best-row{margin-top:10px;font-size:7px}.touch-controls{display:flex;bottom:17px;left:13px;right:13px}.steer{width:52px;height:52px}.handbrake{width:48px;height:51px}.throttle{width:57px;height:70px}.mobile-tip{display:block;font-size:8px}.drift-indicator{top:27%}.toast{top:37%}.pause-card,.result-card{padding:25px}.countdown{font-size:82px}}
@media(max-height:650px) and (max-width:700px){.topbar{height:45px}.overlay-card{transform:scale(.88);transform-origin:left center}.touch-controls{bottom:8px}.speed-hud{bottom:84px}.score-hud{top:48px}.mobile-tip{padding-bottom:3px}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const cars = [
    { name: 'SILVIA S15', specs: 'RWD · 2.0 TURBO · 320 HP', color: '#e9e9df', accent: '#a4f52d', power: 1.02, grip: 1.0 },
    { name: 'RX-7 FD', specs: 'RWD · 1.3 ROTARY · 350 HP', color: '#fa594b', accent: '#ffd057', power: 1.1, grip: .92 },
    { name: 'AE86 TRUENO', specs: 'RWD · 1.6 NA · 210 HP', color: '#f0f0eb', accent: '#ef5b4c', power: .88, grip: 1.12 },
    { name: 'SKYLINE R34', specs: 'AWD · 2.6 TWIN TURBO · 400 HP', color: '#4d91e9', accent: '#b5e3ff', power: 1.18, grip: .9 }
  ];
  const world = { rx: 610, ry: 355, road: 248 };
  let carIndex = 0, running = false, paused = false, started = false;
  let width = 0, height = 0, dpr = 1, last = 0, score = 0, combo = 1, bestCombo = 1, angleTime = 0;
  let toastTimer = 0, audioCtx = null, engineOsc = null, soundOn = false;
  const keys = Object.create(null), touch = { left: false, right: false, gas: false, handbrake: false };
  const car = { x: 0, y: world.ry, vx: 0, vy: 0, heading: 0, steer: 0, speed: 0, drift: 0 };
  const camera = { x: car.x, y: car.y };
  const dust = [];
  let best = Number(localStorage.getItem('neonslide-best') || 0);

  function resize() {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    width = Math.max(1, rect.width); height = Math.max(1, rect.height);
    canvas.width = Math.round(width * dpr); canvas.height = Math.round(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener('resize', resize); resize();

  function updateCarInfo() {
    const c = cars[carIndex];
    $('carName').textContent = c.name; $('carSpecs').textContent = c.specs; $('sideCar').textContent = c.name;
  }
  $('prevCar').addEventListener('click', () => { carIndex = (carIndex + cars.length - 1) % cars.length; updateCarInfo(); });
  $('nextCar').addEventListener('click', () => { carIndex = (carIndex + 1) % cars.length; updateCarInfo(); });
  $('bestScore').textContent = String(best).padStart(6, '0');

  function reset() {
    score = 0; combo = 1; bestCombo = 1; angleTime = 0;
    car.x = 0; car.y = world.ry; car.vx = 0; car.vy = 0; car.heading = 0; car.steer = 0; car.speed = 0; car.drift = 0;
    camera.x = car.x; camera.y = car.y;
    $('scoreValue').textContent = '000000'; $('comboBadge').textContent = 'x1.0'; $('comboText').textContent = 'BUILD YOUR LINE';
    $('driftIndicator').classList.remove('active'); $('overlay').classList.add('hidden'); $('pauseOverlay').classList.add('hidden'); $('resultOverlay').classList.add('hidden');
    paused = false; running = true; started = true;
    $('sessionLabel').textContent = 'FREE RUN'; $('pauseBtn').style.visibility = 'visible';
    last = performance.now(); requestAnimationFrame(loop);
  }
  $('startBtn').addEventListener('click', reset);
  $('againBtn').addEventListener('click', reset);
  $('pauseBtn').addEventListener('click', () => {
    if (!started || !running) return;
    paused = true; running = false; $('pauseOverlay').classList.remove('hidden');
  });
  $('resumeBtn').addEventListener('click', () => { paused = false; running = true; $('pauseOverlay').classList.add('hidden'); last = performance.now(); requestAnimationFrame(loop); });
  $('restartBtn').addEventListener('click', reset);

  window.addEventListener('keydown', e => {
    if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)) e.preventDefault();
    keys[e.key.toLowerCase()] = true;
    if (e.key === 'Escape' && running) $('pauseBtn').click();
  });
  window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });
  window.addEventListener('blur', () => { Object.keys(keys).forEach(k => keys[k] = false); Object.keys(touch).forEach(k => touch[k] = false); });
  document.querySelectorAll('[data-control]').forEach(btn => {
    const name = btn.dataset.control;
    const press = e => { e.preventDefault(); touch[name] = true; btn.classList.add('pressed'); if (btn.setPointerCapture && e.pointerId != null) btn.setPointerCapture(e.pointerId); };
    const release = e => { e.preventDefault(); touch[name] = false; btn.classList.remove('pressed'); };
    btn.addEventListener('pointerdown', press); btn.addEventListener('pointerup', release); btn.addEventListener('pointercancel', release); btn.addEventListener('lostpointercapture', release);
  });

  $('soundBtn').addEventListener('click', () => {
    soundOn = !soundOn; $('soundIcon').textContent = soundOn ? '♫' : '♪'; $('soundBtn').style.color = soundOn ? 'var(--lime)' : '#858d97';
    if (soundOn) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (AC) { audioCtx = audioCtx || new AC(); audioCtx.resume(); if (!engineOsc) { engineOsc = audioCtx.createOscillator(); const gain = audioCtx.createGain(); gain.gain.value = .018; engineOsc.type = 'sawtooth'; engineOsc.frequency.value = 58; engineOsc.connect(gain); gain.connect(audioCtx.destination); engineOsc.start(); engineOsc.gainNode = gain; } }
    } else if (engineOsc && audioCtx) { engineOsc.gainNode.gain.setTargetAtTime(0, audioCtx.currentTime, .05); }
  });

  function inputs() {
    const left = keys.a || keys.arrowleft || touch.left, right = keys.d || keys.arrowright || touch.right;
    return { steer: (right ? 1 : 0) - (left ? 1 : 0), gas: keys.w || keys.arrowup || touch.gas, brake: keys.s || keys.arrowdown, handbrake: keys[' '] || touch.handbrake };
  }
  function trackDistance(x, y) {
    const t = Math.atan2(y / world.ry, x / world.rx);
    const px = world.rx * Math.cos(t), py = world.ry * Math.sin(t);
    return Math.hypot(x - px, y - py);
  }
  function update(dt) {
    const input = inputs(), spec = cars[carIndex], speedBefore = Math.hypot(car.vx, car.vy);
    const forwardX = Math.cos(car.heading), forwardY = Math.sin(car.heading);
    const forwardSpeed = car.vx * forwardX + car.vy * forwardY;
    const sideSpeed = car.vx * -forwardY + car.vy * forwardX;
    const gas = input.gas ? 1 : 0, brake = input.brake ? 1 : 0;
    const accel = 360 * spec.power;
    car.vx += forwardX * (gas * accel - brake * 230 - (forwardSpeed > 0 ? 35 : -35)) * dt;
    car.vy += forwardY * (gas * accel - brake * 230 - (forwardSpeed > 0 ? 35 : -35)) * dt;
    const speedFactor = Math.min(speedBefore / 60, 1.35);
    const handbrake = input.handbrake;
    const maxTurn = handbrake ? 2.35 : 1.72;
    const steeringTarget = input.steer * maxTurn * speedFactor * (forwardSpeed >= 0 ? 1 : -1);
    car.steer += (steeringTarget - car.steer) * Math.min(1, dt * 7);
    car.heading += car.steer * dt;
    const fx = Math.cos(car.heading), fy = Math.sin(car.heading);
    const forward = car.vx * fx + car.vy * fy, lateral = car.vx * -fy + car.vy * fx;
    const grip = handbrake ? .993 : Math.max(.80, .91 + (1 - spec.grip) * .1);
    const lateralNew = lateral * Math.pow(grip, dt * 60);
    const forwardNew = forward * Math.pow(.996, dt * 60);
    car.vx = fx * forwardNew - fy * lateralNew; car.vy = fy * forwardNew + fx * lateralNew;
    car.x += car.vx * dt; car.y += car.vy * dt;
    const distance = trackDistance(car.x, car.y), half = world.road / 2;
    const offroad = distance > half - 8;
    if (distance > half + 20) {
      const t = Math.atan2(car.y / world.ry, car.x / world.rx), nx = Math.cos(t), ny = Math.sin(t);
      car.x -= nx * (distance - half - 20) * .2; car.y -= ny * (distance - half - 20) * .2;
      car.vx *= .94; car.vy *= .94;
    }
    car.speed = Math.hypot(car.vx, car.vy);
    const velAngle = car.speed > 2 ? Math.atan2(car.vy, car.vx) : car.heading;
    let slip = Math.atan2(Math.sin(velAngle - car.heading), Math.cos(velAngle - car.heading));
    if (car.speed < 17) slip = 0;
    car.drift = slip;
    const drifting = Math.abs(slip) > .20 && car.speed > 35 && !offroad;
    if (drifting) {
      angleTime += dt; combo = Math.min(5, combo + dt * .20); bestCombo = Math.max(bestCombo, combo);
      const angleFactor = Math.min(Math.abs(slip) / .72, 1.7), speedFactorScore = Math.min(car.speed / 125, 1.45);
      score += Math.round((angleFactor * speedFactorScore * combo * 72 + (handbrake ? 8 : 0)) * dt);
      $('driftIndicator').classList.add('active'); $('comboText').textContent = slip > 0 ? 'LEFT HAND STYLE' : 'RIGHT HAND STYLE';
      if (Math.random() < .35) dust.push({x:car.x - fx * 27, y:car.y - fy * 27, life:.6, size:7 + Math.random()*8});
    } else {
      $('driftIndicator').classList.remove('active');
      combo = Math.max(1, combo - dt * 1.5);
      $('comboText').textContent = combo > 1.05 ? 'HOLD THAT COMBO' : 'BUILD YOUR LINE';
    }
    if (offroad && speedBefore > 55) { car.vx *= .985; car.vy *= .985; }
    camera.x += (car.x - camera.x) * Math.min(1, dt * 5); camera.y += (car.y - camera.y) * Math.min(1, dt * 5);
    $('scoreValue').textContent = String(Math.floor(score)).padStart(6, '0');
    $('comboBadge').textContent = 'x' + combo.toFixed(1);
    $('speedValue').textContent = String(Math.round(car.speed * .72)).padStart(3, '0');
    $('speedBar').style.width = Math.min(100, car.speed / 2.1) + '%';
    if (toastTimer > 0) { toastTimer -= dt; if (toastTimer <= 0) $('toast').classList.remove('show'); }
    if (audioCtx && engineOsc && soundOn) engineOsc.frequency.setTargetAtTime(48 + car.speed * .42 + (gas ? 20 : 0), audioCtx.currentTime, .08);
    dust.forEach(p => p.life -= dt); while (dust.length && dust[0].life <= 0) dust.shift();
  }

  function render(now) {
    const sx = Math.min(width / 1460, height / 1040), ox = width / 2 - camera.x * sx, oy = height / 2 - camera.y * sx;
    ctx.clearRect(0,0,width,height); ctx.save(); ctx.translate(ox,oy); ctx.scale(sx,sx);
    drawGround(now); drawTrack(now); drawDust(); drawCar(); ctx.restore();
